/// One source, normalised.
#[derive(Clone, Debug, PartialEq)]
pub struct SourceState {
	pub kind: SourceKind,
	pub present: Tristate,
	pub online: Tristate,
	pub charge: ChargeState,
	pub remaining: Capacity,
	pub full: Capacity,
	pub design: Capacity,
	/// Basis points, 0 to 10000.
	pub state_of_charge: MeasureU64,
	/// Microvolts.
	pub voltage: MeasureU64,
	/// Microamps: positive into the source's storage, negative delivered out of it.
	pub current: MeasureI64,
	/// Microwatts, signed as `current` is. A source that reports only the watts it delivers publishes
	/// them here, and no load fraction is invented from them.
	pub power: MeasureI64,
	/// Whole seconds.
	pub runtime: MeasureU64,
	/// Basis points of rated load.
	pub load: MeasureU64,
	pub temperature: Temperature,
	pub trips: Vec<TripPoint>,
	pub alarms: Vec<Alarm>,
	pub controls: Controls,
	/// The source's own time, when it gave one. Never synchronised with anything.
	pub source_time: Option<u64>,
}

impl SourceState {
	pub fn encode(&self, out: &mut [u8]) -> Option<usize> {
		let mut w = SliceWriter::new(out);
		self.write(&mut w)?;
		// `finish` refuses while a capability is recorded, because returning the
		// length alone would drop it.
		w.finish()
	}
	pub fn encode_vec(&self) -> Option<Vec<u8>> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		// `into_inner` refuses while a capability is recorded, because returning
		// the bytes alone would drop it.
		w.into_inner()
	}
	pub fn encode_message(&self) -> Option<(Vec<u8>, Handles)> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		Some(w.into_message())
	}
	pub fn decode(bytes: &[u8]) -> Option<SourceState> {
		let mut r = Reader::new(bytes);
		let value = SourceState::read(&mut r)?;
		r.finish()?;
		Some(value)
	}
	pub fn decode_message(bytes: &[u8], handles: &mut Handles) -> Option<SourceState> {
		let mut r = Reader::with_handles(bytes, handles);
		let value = SourceState::read(&mut r)?;
		r.finish()?;
		// The frame is good, so the capabilities it carried are the value's now. A
		// refusal above leaves them in the caller's list, which is the half that closes.
		handles.clear();
		Some(value)
	}
	pub fn write<W: Sink>(&self, w: &mut W) -> Option<()> {
		self.kind.write(w)?;
		self.present.write(w)?;
		self.online.write(w)?;
		self.charge.write(w)?;
		self.remaining.write(w)?;
		self.full.write(w)?;
		self.design.write(w)?;
		self.state_of_charge.write(w)?;
		self.voltage.write(w)?;
		self.current.write(w)?;
		self.power.write(w)?;
		self.runtime.write(w)?;
		self.load.write(w)?;
		self.temperature.write(w)?;
		if self.trips.len() > u16::MAX as usize {
			return None;
		}
		w.u16(self.trips.len() as u16)?;
		for v0 in self.trips.iter() {
			v0.write(w)?;
		}
		if self.alarms.len() > u16::MAX as usize {
			return None;
		}
		w.u16(self.alarms.len() as u16)?;
		for v1 in self.alarms.iter() {
			v1.write(w)?;
		}
		self.controls.write(w)?;
		match &self.source_time {
			Some(v2) => {
				w.u8(1)?;
				w.u64(*v2)?;
			}
			None => {
				w.u8(0)?;
			}
		}
		Some(())
	}
	pub fn read(r: &mut Reader) -> Option<SourceState> {
		let kind = SourceKind::read(r)?;
		let present = Tristate::read(r)?;
		let online = Tristate::read(r)?;
		let charge = ChargeState::read(r)?;
		let remaining = Capacity::read(r)?;
		let full = Capacity::read(r)?;
		let design = Capacity::read(r)?;
		let state_of_charge = MeasureU64::read(r)?;
		let voltage = MeasureU64::read(r)?;
		let current = MeasureI64::read(r)?;
		let power = MeasureI64::read(r)?;
		let runtime = MeasureU64::read(r)?;
		let load = MeasureU64::read(r)?;
		let temperature = Temperature::read(r)?;
		let trips = {
			let v3 = r.u16()? as usize;
			let v3 = (v3 <= 16).then_some(v3)?;
			let mut v4 = Vec::new();
			v4.try_reserve_exact(v3).ok()?;
			for _ in 0..v3 {
				v4.push(TripPoint::read(r)?);
			}
			v4
		};
		let alarms = {
			let v5 = r.u16()? as usize;
			let v5 = (v5 <= 16).then_some(v5)?;
			let mut v6 = Vec::new();
			v6.try_reserve_exact(v5).ok()?;
			for _ in 0..v5 {
				v6.push(Alarm::read(r)?);
			}
			v6
		};
		let controls = Controls::read(r)?;
		let source_time = if r.tag()? { Some(r.u64()?) } else { None };
		Some(SourceState { kind, present, online, charge, remaining, full, design, state_of_charge, voltage, current, power, runtime, load, temperature, trips, alarms, controls, source_time })
	}
}

