/// One frame of a provider's stream, carrying the provider's own monotonic revision.
#[derive(Clone, Debug, PartialEq)]
pub struct ProviderUpdate {
	pub revision: u64,
	pub kind: ProviderUpdateKind,
	pub source: Option<ProviderSource>,
	pub gone: Option<u32>,
}

impl ProviderUpdate {
	pub fn encode(&self, out: &mut [u8]) -> Option<usize> {
		let mut w = SliceWriter::new(out);
		self.write(&mut w)?;
		// `finish` refuses while a capability is recorded, because returning the
		// length alone would drop it.
		w.finish()
	}
	pub fn encode_vec(&self) -> Option<Vec<u8>> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		// `into_inner` refuses while a capability is recorded, because returning
		// the bytes alone would drop it.
		w.into_inner()
	}
	pub fn encode_message(&self) -> Option<(Vec<u8>, Handles)> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		Some(w.into_message())
	}
	pub fn decode(bytes: &[u8]) -> Option<ProviderUpdate> {
		let mut r = Reader::new(bytes);
		let value = ProviderUpdate::read(&mut r)?;
		r.finish()?;
		Some(value)
	}
	pub fn decode_message(bytes: &[u8], handles: &mut Handles) -> Option<ProviderUpdate> {
		let mut r = Reader::with_handles(bytes, handles);
		let value = ProviderUpdate::read(&mut r)?;
		r.finish()?;
		// The frame is good, so the capabilities it carried are the value's now. A
		// refusal above leaves them in the caller's list, which is the half that closes.
		handles.clear();
		Some(value)
	}
	pub fn write<W: Sink>(&self, w: &mut W) -> Option<()> {
		w.u64(self.revision)?;
		self.kind.write(w)?;
		match &self.source {
			Some(v20) => {
				w.u8(1)?;
				v20.write(w)?;
			}
			None => {
				w.u8(0)?;
			}
		}
		match &self.gone {
			Some(v21) => {
				w.u8(1)?;
				w.u32(*v21)?;
			}
			None => {
				w.u8(0)?;
			}
		}
		Some(())
	}
	pub fn read(r: &mut Reader) -> Option<ProviderUpdate> {
		let revision = r.u64()?;
		let kind = ProviderUpdateKind::read(r)?;
		let source = if r.tag()? { Some(ProviderSource::read(r)?) } else { None };
		let gone = if r.tag()? { Some(r.u32()?) } else { None };
		Some(ProviderUpdate { revision, kind, source, gone })
	}
}

